17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.regex.Pattern;
24	
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerHouseholdException;
29	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
30	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
31	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
32	import org.springframework.samples.petclinic.rest.advice.OwnerCityFullException;
33	import org.springframework.samples.petclinic.rest.advice.OwnerDailyLimitException;
34	import org.springframework.samples.petclinic.mapper.OwnerMapper;
35	import org.springframework.samples.petclinic.mapper.PetMapper;
36	import org.springframework.samples.petclinic.mapper.VisitMapper;
37	import org.springframework.samples.petclinic.model.Owner;
38	import org.springframework.samples.petclinic.model.Pet;
39	import org.springframework.samples.petclinic.model.Visit;
40	import org.springframework.samples.petclinic.rest.api.OwnersApi;
41	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
42	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.PetDto;
44	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
47	import org.springframework.samples.petclinic.service.ClinicService;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.util.StringUtils;
50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    /**
67	     * Basic syntactic check for an email address: a non-empty local part, an '@', and a domain with
68	     * at least one dot and a two-or-more letter top-level label. Case is ignored here; accepted
69	     * addresses are lower-cased before being stored.
70	     */
71	    private static final Pattern EMAIL_PATTERN =
72	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
73	
74	    /**
75	     * Maximum number of owners a single city may contain. A create that would take the owner's city
76	     * to more than this many owners - i.e. the city already holds this many - is rejected with a 409.
77	     */
78	    private static final int CITY_OWNER_LIMIT = 50;
79	
80	    /**
81	     * Maximum number of owners that may be registered on a single day. A create that would take the
82	     * number of owners sharing a {@code registrationDate} beyond this many - i.e. that many owners
83	     * have already been created that day - is rejected with a 429.
84	     */
85	    private static final int DAILY_OWNER_LIMIT = 100;
86	
87	    private final ClinicService clinicService;
88	
89	    private final OwnerMapper ownerMapper;
90	
91	    private final PetMapper petMapper;
92	
93	    private final VisitMapper visitMapper;
94	
95	    public OwnerRestControllerV1(ClinicService clinicService,
96	                                 OwnerMapper ownerMapper,
97	                                 PetMapper petMapper,
98	                                 VisitMapper visitMapper) {
99	        this.clinicService = clinicService;
100	        this.ownerMapper = ownerMapper;
101	        this.petMapper = petMapper;
102	        this.visitMapper = visitMapper;
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
108	        Collection<Owner> owners;
109	        if (lastName != null) {
110	            owners = this.clinicService.findOwnerByLastName(lastName);
111	        } else {
112	            owners = this.clinicService.findAllOwners();
113	        }
114	        if (owners.isEmpty()) {
115	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
116	        }
117	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
118	    }
119	
120	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
121	    @Override
122	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
123	        Owner owner = this.clinicService.findOwnerById(ownerId);
124	        if (owner == null) {
125	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
126	        }
127	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
128	    }
129	
130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
133	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
134	        validateRequiredFields(ownerFieldsDto);
135	        HttpHeaders headers = new HttpHeaders();
136	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
137	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
138	        owner.setEmail(normalizeEmail(owner.getEmail()));
139	        if (owner.getRegistrationDate() == null) {
140	            owner.setRegistrationDate(LocalDate.now());
141	        }
142	        if (!this.clinicService.findOwnerByTelephone(owner.getTelephone()).isEmpty()) {
143	            throw new DuplicateOwnerTelephoneException(owner.getTelephone());
144	        }
145	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
146	            && isDuplicateHousehold(owner.getLastName(), owner.getAddress())) {
147	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getAddress());
148	        }
149	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
150	            throw new OwnerCityFullException(owner.getCity());
151	        }
152	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= DAILY_OWNER_LIMIT) {
153	            throw new OwnerDailyLimitException(owner.getRegistrationDate());
154	        }
155	        owner.setCustomerCode(buildCustomerCode(owner.getCity(), owner.getLastName()));
156	        owner.setHouseholdId(HouseholdNormalizer.householdId(owner.getLastName(), owner.getAddress()));
157	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
158	        this.clinicService.saveOwner(owner);
159	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
160	        headers.setLocation(UriComponentsBuilder.newInstance()
161	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
162	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
163	    }
164	
165	    /**
166	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
167	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
168	     * so the client receives a 400 whose {@code errors} array lists each missing field. The address is
169	     * checked in its {@link AddressNormalizer#normalize normalized} form, so a value that is blank only
170	     * after normalization is still rejected.
171	     *
172	     * @param ownerFieldsDto the submitted owner fields
173	     */
174	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
175	        List<String> missingFields = new ArrayList<>();
176	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
177	            missingFields.add("firstName");
178	        }
179	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
180	            missingFields.add("lastName");
181	        }
182	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
183	            missingFields.add("address");
184	        }
185	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
186	            missingFields.add("city");
187	        }
188	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
189	            missingFields.add("telephone");
190	        }
191	        if (!missingFields.isEmpty()) {
192	            throw new MissingOwnerFieldsException(missingFields);
193	        }
194	    }
195	
196	    /**
197	     * Normalizes an optional email address for owner creation. Email is optional, so a missing or
198	     * blank value is left untouched. When a value is supplied it must be a syntactically valid
199	     * address; the accepted value is lower-cased before it is stored and returned.
200	     *
201	     * @param email the raw email value submitted by the client, or {@code null}
202	     * @return the lower-cased email, or the original blank/{@code null} value when none was supplied
203	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
204	     */
205	    private String normalizeEmail(String email) {
206	        if (!StringUtils.hasText(email)) {
207	            return email;
208	        }
209	        if (!EMAIL_PATTERN.matcher(email).matches()) {
210	            throw new InvalidOwnerFieldsException(List.of("email"));
211	        }
212	        return email.toLowerCase();
213	    }
214	
215	    /**
216	     * Builds the owner's customer code formatted {@code <CITY3>-<LAST3>-<NNNN>}, where CITY3 is the
217	     * upper-cased first three letters of the city, LAST3 is the upper-cased first three letters of the
218	     * last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more than the number
219	     * of owners already in that city (e.g. {@code SYD-SMI-0007}).
220	     *
221	     * @param city the owner's city
222	     * @param lastName the owner's last name
223	     * @return the assigned customer code
224	     */
225	    private String buildCustomerCode(String city, String lastName) {
226	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
227	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
228	        int sequence = (int) this.clinicService.findAllOwners().stream()
229	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
230	            .count() + 1;
231	        return String.format("%s-%s-%04d", city3, last3, sequence);
232	    }
233	
234	    /**
235	     * Determines whether an existing owner already shares a household with the supplied last name and
236	     * address. Two owners belong to the same household when {@link HouseholdNormalizer#sameHousehold}
237	     * considers their last name and address a match.
238	     *
239	     * @param lastName the submitted owner's last name
240	     * @param address the submitted owner's address
241	     * @return {@code true} if another owner already has the same normalized last name and address
242	     */
243	    /**
244	     * Counts how many owners already exist that share the supplied first and last name, compared
245	     * case-insensitively. This reflects the number of namesakes present <em>before</em> the current
246	     * owner is created and is stored on the new owner as its {@code namesakeCount}.
247	     *
248	     * @param firstName the submitted owner's first name
249	     * @param lastName the submitted owner's last name
250	     * @return the number of existing owners with the same first and last name, ignoring case
251	     */
252	    private int countNamesakes(String firstName, String lastName) {
253	        return (int) this.clinicService.findAllOwners().stream()
254	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
255	                && lastName.equalsIgnoreCase(existing.getLastName()))
256	            .count();
257	    }
258	
259	    private boolean isDuplicateHousehold(String lastName, String address) {
260	        return this.clinicService.findAllOwners().stream()
261	            .anyMatch(existing -> HouseholdNormalizer.sameHousehold(
262	                lastName, address, existing.getLastName(), existing.getAddress()));
263	    }
264	
265	    /**
266	     * Counts how many owners already live in the supplied city, compared case-insensitively. Used to
267	     * enforce the per-city capacity limit when a new owner is created.
268	     *
269	     * @param city the submitted owner's city
270	     * @return the number of existing owners in that city, ignoring case
271	     */
272	    private long countOwnersInCity(String city) {
273	        return this.clinicService.findAllOwners().stream()
274	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
275	            .count();
276	    }
277	
278	    /**
279	     * Counts how many owners have already been created on the supplied registration date. Used to
280	     * enforce the per-day capacity limit when a new owner is created.
281	     *
282	     * @param registrationDate the registration date of the owner being created
283	     * @return the number of existing owners already registered on that date
284	     */
285	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
286	        return this.clinicService.findAllOwners().stream()
287	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
288	            .count();
289	    }
290	
291	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
292	    @Override
293	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
294	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
295	        if (currentOwner == null) {
296	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
297	        }
298	        currentOwner.setAddress(ownerFieldsDto.getAddress());
299	        currentOwner.setCity(ownerFieldsDto.getCity());
300	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
301	        currentOwner.setLastName(ownerFieldsDto.getLastName());
302	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
303	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
304	        this.clinicService.saveOwner(currentOwner);
305	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
306	    }
307	
308	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
309	    @Transactional
310	    @Override
311	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
312	        Owner owner = this.clinicService.findOwnerById(ownerId);
313	        if (owner == null) {
314	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
315	        }
316	        this.clinicService.deleteOwner(owner);
317	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
318	    }
319	
320	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
321	    @Override
322	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
323	        Owner owner = this.clinicService.findOwnerById(ownerId);
324	        if (owner == null) {
325	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
326	        }
327	        HttpHeaders headers = new HttpHeaders();
328	        Pet pet = petMapper.toPet(petFieldsDto);
329	        owner.setId(ownerId);
330	        pet.setOwner(owner);
331	        pet.getType().setName(null);
332	        this.clinicService.savePet(pet);
333	        PetDto petDto = petMapper.toPetDto(pet);
334	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
335	            .buildAndExpand(pet.getId()).toUri());
336	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
337	    }
338	
339	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
340	    @Override
341	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
342	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
343	        if (currentOwner != null) {
344	            Pet currentPet = this.clinicService.findPetById(petId);
345	            if (currentPet != null) {
346	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
347	                currentPet.setName(petFieldsDto.getName());
348	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
349	                this.clinicService.savePet(currentPet);
350	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
351	            }
352	        }
353	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
354	    }
355	
356	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
357	    @Override
358	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
359	        HttpHeaders headers = new HttpHeaders();
360	        Visit visit = visitMapper.toVisit(visitFieldsDto);
361	        Pet pet = new Pet();
362	        pet.setId(petId);
363	        visit.setPet(pet);
364	        this.clinicService.saveVisit(visit);
365	        VisitDto visitDto = visitMapper.toVisitDto(visit);
366	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
367	            .buildAndExpand(visit.getId()).toUri());
368	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
369	    }
370	
371	
372	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
373	    @Override
374	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
375	        Owner owner = this.clinicService.findOwnerById(ownerId);
376	        if (owner != null) {
377	            Pet pet = owner.getPet(petId);
378	            if (pet != null) {
379	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
380	            }
381	        }
382	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
383	    }
384	}
